package com.example.clinometer.reports.data

/**
 * Типове доклади за съобщаване на карта
 */
enum class ReportType(val displayName: String, val icon: String) {
    POLICE("Полиция", "🚔"),
    CAMERA("Камера", "📹"),
    ACCIDENT("Инцидент", "⚠️"),
    HAZARD("Опасност", "⚡"),
    TRAFFIC("Трафик", "🚦"),
    ROADWORK("Ремонт", "🚧");
    
    companion object {
        fun fromString(value: String): ReportType? {
            return entries.find { it.name == value }
        }
    }
}
